344	/// Inserts a `NewlineSequence` at position `at` and returns the length of `NewlineSequence` inserted.
345	/// The return value is used to calculate the new `at` in a later point.
346	fn insert_after_span(
347	    at: usize,
348	    newline_sequence: NewlineSequence,
349	    formatted_code: &mut FormattedCode,
350	    threshold: usize,
351	) -> Result<i64, FormatterError> {
352	    let sequence_string = format_newline_sequence(&newline_sequence, threshold);
353	    let mut len = sequence_string.len() as i64;
354	    let mut src_rope = Rope::from_str(formatted_code);
355	
356	    let at = byte_to_char_idx(formatted_code, at);
357	
358	    // Remove the previous sequence_length, that will be replaced in the next statement
359	    let mut remove_until = at;
360	    for i in at..at + newline_sequence.sequence_length {
361	        if !is_new_line_in_rope(&src_rope, i) {
362	            break;
363	        }
364	        remove_until = i;
365	    }
366	    let removed = if remove_until > at {
367	        src_rope
368	            .try_remove(at..remove_until)
369	            .map_err(|_| FormatterError::NewlineSequenceError)?;
370	        let removed = (remove_until - at) as i64;
371	        len -= removed;
372	        removed
373	    } else {
374	        0
375	    };
376	
377	    // Do never insert the newline sequence between two alphanumeric characters
378	    let is_token = src_rope
379	        .get_char(at)
380	        .map(is_alphanumeric)
381	        .unwrap_or_default()
382	        && src_rope
383	            .get_char(at + 1)
384	            .map(is_alphanumeric)
385	            .unwrap_or_default();
386	
387	    if !is_token {
388	        src_rope
389	            .try_insert(at, &sequence_string)
390	            .map_err(|_| FormatterError::NewlineSequenceError)?;
391	    } else {
392	        len = -removed;
393	    }
394	
395	    formatted_code.clear();
396	    formatted_code.push_str(&src_rope.to_string());
397	    Ok(len)
398	}
